def top_k(lst, k):
    # Fill in your code here
    sort_lst=sort(lst)
    return sort_lst[:k]

def sort(lst):
    sort=[]
    while lst:
        largest=lst[0]
        for elem in lst:
            if elem > largest:
                largest = elem
        lst.remove(largest)
        sort.append(largest)
    return sort

def top_k(lst, k):
    counter = []
    while len(counter) < k:
        counter.append(lst.pop(lst.index(max(lst))))
    return counter

def top_k(lst, k):
    new_lst = []
    counter = 1
    while counter <= k:
        highest = lst[0]  # arbitrary number in list 
        for x in lst: 
            if x > highest:
                highest = x
        new_lst.append(highest)
        lst.remove(highest)
        counter +=1

    return new_lst
